def box(m, a, b, bv=0.3, **k):
    d = {'part': 'box', 'mat': m, 'from': a, 'to': b, 'geom': True, 'bevel': bv}; d.update(k); return d
def cyl(m, a, b, r, bv=0.2, **k):
    d = {'part': 'cyl', 'mat': m, 'from': a, 'to': b, 'r': r, 'geom': True, 'bevel': bv}; d.update(k); return d
def pot(body, lid=None, h=7, r=5.5, handles='iron', y0=4, content=None):
    p = [cyl(body, [8, y0, 8], [8, y0 + h, 8], r, 0.7)]
    if content: p.append(cyl(content, [8, y0 + h - 0.6, 8], [8, y0 + h + 0.1, 8], r - 0.8, 0.2))
    if lid: p += [cyl(lid, [8, y0 + h, 8], [8, y0 + h + 0.9, 8], r + 0.1, 0.4), cyl(lid, [8, y0 + h + 0.9, 8], [8, y0 + h + 1.9, 8], 0.8, 0.3)]
    if handles: p += [box(handles, [8 + r - 0.3, y0 + h - 2.5, 7.2], [8 + r + 2.2, y0 + h - 1.5, 8.8], 0.3), box(handles, [8 - r - 2.2, y0 + h - 2.5, 7.2], [8 - r + 0.3, y0 + h - 1.5, 8.8], 0.3)]
    return p
def pan(body, r=6, h=1.6, handle='wood', inside=None, y0=6):
    p = [cyl(body, [8, y0, 8], [8, y0 + h, 8], r, 0.5)]
    if inside: p.append(cyl(inside, [8, y0 + h - 0.5, 8], [8, y0 + h + 0.05, 8], r - 0.9, 0.2))
    p.append(box(handle, [8 + r - 0.5, y0 + h - 1.2, 7.3], [8 + r + 5, y0 + h - 0.2, 8.7], 0.4))
    return p
def tray(body, w=11, d=7, h=1.2, inside=None):
    p = [box(body, [8 - w / 2, 6, 8 - d / 2], [8 + w / 2, 6 + h, 8 + d / 2], 0.3)]
    if inside: p.append(box(inside, [8 - w / 2 + 0.8, 6 + h - 0.4, 8 - d / 2 + 0.8], [8 + w / 2 - 0.8, 6 + h + 0.4, 8 + d / 2 - 0.8], 0.3))
    return p
def oven(body, door, fire='glow', w=10, h=9, d=9, domed=False):
    p = [box(body, [8 - w / 2, 3, 8 - d / 2], [8 + w / 2, 3 + h, 8 + d / 2], 0.5)]
    if domed: p.append(cyl(body, [8, 3 + h, 8], [8, 3 + h + 2.5, 8], w / 2 - 0.8, 1.2))
    p += [box(fire, [8 - 2.6, 4, 8 + d / 2 - 0.2], [8 + 2.6, 7.4, 8 + d / 2 + 0.3], 0.3), box(door, [8 - 3.2, 3.4, 8 + d / 2 - 0.1], [8 + 3.2, 8, 8 + d / 2 + 0.5], 0.3)]
    return p
